for(const [id,k]of [['title','title'],['roomW','W'],['roomH','H'],['unit','unit']])$(id).onchange=()=>{let v=$(id).value;if(k==='W'||k==='H'){v=Number(v);if(!Number.isFinite(v)||v<5||v>500){toast('Enter a warehouse dimension between 5 and 500.');render();return}}if(k==='unit'&&v!==state.unit&&v!=='grid'&&state.unit!=='grid'){checkpoint();let f=v==='m'?.3048:1/.3048;state.W=Math.round(state.W*f*100)/100;state.H=Math.round(state.H*f*100)/100;if(state.W<5||state.H<5||state.W>500||state.H>500){state=history.pop();toast('Converted dimensions must stay between 5 and 500.');render();return}state.items.forEach(o=>{for(const p of ['x','y','w','h'])o[p]=Math.round(o[p]*f*100)/100})}else checkpoint();state[k]=typeof v==='string'?v.slice(0,150):v;state.items.forEach(clamp);commit()};
